TRUNCATE TABLE [int_gd20];
WITH r_mat AS (SELECT k, v1 FROM (SELECT codigo AS k, descripcion AS v1, ROW_NUMBER() OVER (PARTITION BY codigo ORDER BY id) AS rn FROM int_ref_material WHERE codigo IS NOT NULL AND codigo <> 0) x WHERE rn = 1),
r_vend AS (SELECT k, v1, v2, v3 FROM (SELECT UPPER(LTRIM(RTRIM(vendedor_sap))) AS k, vendedor AS v1, vendedor_ok AS v2, equipo AS v3, ROW_NUMBER() OVER (PARTITION BY UPPER(LTRIM(RTRIM(vendedor_sap))) ORDER BY id) AS rn FROM int_ref_equipo WHERE vendedor_sap IS NOT NULL AND vendedor_sap <> '') x WHERE rn = 1),
r_grp AS (SELECT k, v1 FROM (SELECT UPPER(LTRIM(RTRIM(grupo_vendedores))) AS k, equipo AS v1, ROW_NUMBER() OVER (PARTITION BY UPPER(LTRIM(RTRIM(grupo_vendedores))) ORDER BY id) AS rn FROM int_ref_equipo WHERE grupo_vendedores IS NOT NULL AND grupo_vendedores <> '') x WHERE rn = 1),
r_eq AS (SELECT k, v1 FROM (SELECT UPPER(LTRIM(RTRIM(equipo))) AS k, gerencia AS v1, ROW_NUMBER() OVER (PARTITION BY UPPER(LTRIM(RTRIM(equipo))) ORDER BY id) AS rn FROM int_ref_equipo WHERE equipo IS NOT NULL AND equipo <> '') x WHERE rn = 1),
r_seg AS (SELECT k, v1 FROM (SELECT UPPER(LTRIM(RTRIM(descripcion_sap))) AS k, segmento AS v1, ROW_NUMBER() OVER (PARTITION BY UPPER(LTRIM(RTRIM(descripcion_sap))) ORDER BY id) AS rn FROM int_ref_almacen WHERE descripcion_sap IS NOT NULL AND descripcion_sap <> '') x WHERE rn = 1),
r_can AS (SELECT k, v1 FROM (SELECT UPPER(LTRIM(RTRIM(segmento))) AS k, canal AS v1, ROW_NUMBER() OVER (PARTITION BY UPPER(LTRIM(RTRIM(segmento))) ORDER BY id) AS rn FROM int_ref_almacen WHERE segmento IS NOT NULL AND segmento <> '') x WHERE rn = 1),
r_tipo AS (SELECT k, v1 FROM (SELECT codigo_sap_cliente AS k, tipo AS v1, ROW_NUMBER() OVER (PARTITION BY codigo_sap_cliente ORDER BY id) AS rn FROM int_ref_centro WHERE codigo_sap_cliente IS NOT NULL AND codigo_sap_cliente <> 0) x WHERE rn = 1),
r_cen AS (SELECT k, v1 FROM (SELECT UPPER(LTRIM(RTRIM(centro))) AS k, codigo_sap_cliente AS v1, ROW_NUMBER() OVER (PARTITION BY UPPER(LTRIM(RTRIM(centro))) ORDER BY id) AS rn FROM int_ref_centro WHERE centro IS NOT NULL AND centro <> '') x WHERE rn = 1),
r_loc AS (SELECT k, v1 FROM (SELECT UPPER(LTRIM(RTRIM(localidad_despacho))) AS k, localidad_im AS v1, ROW_NUMBER() OVER (PARTITION BY UPPER(LTRIM(RTRIM(localidad_despacho))) ORDER BY id) AS rn FROM int_ref_localidad WHERE localidad_despacho IS NOT NULL AND localidad_despacho <> '') x WHERE rn = 1),
b AS (SELECT g.*, CASE WHEN (c0.cliente IS NULL OR COALESCE(NULLIF(c0.region_nombre, ''), '0') = '0') THEN g.cliente ELSE g.customer_rebate END AS dest_ef, CASE WHEN (c0.cliente IS NULL OR COALESCE(NULLIF(c0.region_nombre, ''), '0') = '0') THEN g.cliente ELSE g.emisor_orden END AS sol_ef, CASE WHEN (c0.cliente IS NULL OR COALESCE(NULLIF(c0.region_nombre, ''), '0') = '0') THEN g.cliente ELSE g.customer_bill_to END AS bill_ef FROM stg_gd20 g LEFT JOIN int_cartera c0 ON c0.cliente = g.customer_rebate /* DATE_FILTER */),
s1 AS (SELECT b.*, CASE b.unidad_medida_base WHEN 'M3' THEN 'Granel M3' WHEN 'T' THEN 'Granel t' WHEN 'S50' THEN 'Embolsado' WHEN 'PC' THEN 'Bolsas Vacias' ELSE '0' END AS tipo_embalaje, CASE WHEN r_mat.k IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(r_mat.v1 AS NVARCHAR(500)), ''), '0') END AS nombre_producto, (CASE b.unidad_medida_base WHEN 'M3' THEN (b.cantidad * -1) * 1.42 WHEN 'T' THEN b.cantidad * -1 WHEN 'S50' THEN (b.cantidad * -1) / 20.0 ELSE 0 END) * (CASE WHEN b.numero_cuenta = 33111020 THEN -1 ELSE 1 END) AS volumen_toneladas, CASE WHEN c_pag.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_pag.nombre_cliente AS NVARCHAR(500)), ''), '0') END AS nombre_pagador, CASE WHEN c_sol.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_sol.nombre_cliente AS NVARCHAR(500)), ''), '0') END AS nombre_solicitante, CASE WHEN c_dst.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_dst.vendedor AS NVARCHAR(500)), ''), '0') END AS vendedor_sap, CASE WHEN c_dst.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_dst.nombre_cliente AS NVARCHAR(500)), ''), '0') END AS nombre_destinatario, CASE WHEN c_dst.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_dst.poblacion AS NVARCHAR(500)), ''), '0') END AS localidad, CASE WHEN c_dst.cliente IS NULL THEN b.poblacion ELSE COALESCE(NULLIF(CAST(c_dst.attribute_6 AS NVARCHAR(500)), ''), '0') END AS provincia, CASE WHEN c_dst.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_dst.region_nombre AS NVARCHAR(500)), ''), '0') END AS dpto, c_dst.attribute_10 AS sub_canal_key, CASE WHEN r_tipo.k IS NULL THEN 'VENTA DIRECTA' ELSE COALESCE(NULLIF(CAST(r_tipo.v1 AS NVARCHAR(500)), ''), '0') END AS tipo_venta, CASE WHEN c_pag.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_pag.region_nombre AS NVARCHAR(500)), ''), '0') END AS dpto_pagador, CASE WHEN c_pag.cliente IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(c_pag.poblacion AS NVARCHAR(500)), ''), '0') END AS localidad_pagador, CASE WHEN r_cen.k IS NULL THEN b.cliente ELSE COALESCE(r_cen.v1, 0) END AS codigo_cliente, DAY(b.fe_contabilizacion) AS dia, MONTH(b.fe_contabilizacion) AS mes, YEAR(b.fe_contabilizacion) AS anio, CASE WHEN b.numero_cuenta = 33111020 THEN (CASE b.unidad_medida_base WHEN 'M3' THEN (b.cantidad * -1) * 1.42 WHEN 'T' THEN b.cantidad * -1 WHEN 'S50' THEN (b.cantidad * -1) / 20.0 ELSE 0 END) * (CASE WHEN b.numero_cuenta = 33111020 THEN -1 ELSE 1 END) END AS bonificaciones, 'OTROS' AS centro_distribucion, 'OTROS' AS zona_entrega FROM b LEFT JOIN int_cartera c_pag ON c_pag.cliente = b.cliente LEFT JOIN int_cartera c_sol ON c_sol.cliente = b.sol_ef LEFT JOIN int_cartera c_dst ON c_dst.cliente = b.dest_ef LEFT JOIN r_mat ON r_mat.k = b.material LEFT JOIN r_tipo ON r_tipo.k = b.cliente LEFT JOIN r_cen ON r_cen.k = UPPER(LTRIM(RTRIM(CAST(b.centro AS NVARCHAR(500)))))),
s2 AS (SELECT s1.*, CASE WHEN r_vend.k IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(r_vend.v1 AS NVARCHAR(500)), ''), '0') END AS vendedor, CASE WHEN r_vend.k IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(r_vend.v2 AS NVARCHAR(500)), ''), '0') END AS vendedor_ok, CASE WHEN CHARINDEX('CEMENTO', COALESCE(s1.nombre_producto, '') COLLATE Latin1_General_CS_AS) > 0 THEN CASE WHEN r_vend.k IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(r_vend.v3 AS NVARCHAR(500)), ''), '0') END ELSE CASE WHEN r_grp.k IS NULL THEN 'No encontrado' ELSE COALESCE(NULLIF(CAST(r_grp.v1 AS NVARCHAR(500)), ''), '0') END END AS equipo, CASE WHEN r_seg.k IS NULL THEN 'OTROS' ELSE COALESCE(NULLIF(CAST(r_seg.v1 AS NVARCHAR(500)), ''), '0') END AS sub_canal, CASE WHEN UPPER(s1.dpto) = 'SANTA CRUZ' THEN CASE WHEN r_loc.k IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(r_loc.v1 AS NVARCHAR(500)), ''), '0') END ELSE s1.dpto END AS region_m, CASE WHEN s1.numero_cuenta = 33111020 THEN 0 WHEN (UPPER(s1.dpto) = 'PANDO' AND UPPER(s1.incoterms) = 'CIF') OR (UPPER(s1.dpto) = 'GENERIC' AND UPPER(s1.incoterms) = 'FCA') THEN s1.moneda_sociedad * -1 ELSE (s1.moneda_sociedad / 0.87) * -1 END AS ingreso_bruto FROM s1 LEFT JOIN r_vend ON r_vend.k = UPPER(LTRIM(RTRIM(CAST(s1.vendedor_sap AS NVARCHAR(500))))) LEFT JOIN r_grp ON r_grp.k = UPPER(LTRIM(RTRIM(CAST(s1.grupo_vendedores AS NVARCHAR(500))))) LEFT JOIN r_seg ON r_seg.k = UPPER(LTRIM(RTRIM(CAST(s1.sub_canal_key AS NVARCHAR(500))))) LEFT JOIN r_loc ON r_loc.k = UPPER(LTRIM(RTRIM(CAST(s1.localidad AS NVARCHAR(500)))))),
s3 AS (SELECT s2.*, CASE WHEN r_eq.k IS NULL THEN '0' ELSE COALESCE(NULLIF(CAST(r_eq.v1 AS NVARCHAR(500)), ''), '0') END AS gerencia, CASE WHEN r_can.k IS NULL THEN 'OTROS' ELSE COALESCE(NULLIF(CAST(r_can.v1 AS NVARCHAR(500)), ''), '0') END AS canal FROM s2 LEFT JOIN r_eq ON r_eq.k = UPPER(LTRIM(RTRIM(CAST(s2.equipo AS NVARCHAR(500))))) LEFT JOIN r_can ON r_can.k = UPPER(LTRIM(RTRIM(CAST(s2.sub_canal AS NVARCHAR(500))))))
INSERT INTO [int_gd20] (ejercicio, sociedad, organizacion_ventas, centro, division, oficina_ventas, canal_distribucion, sector, numero_cuenta, centro_beneficio, material, unidad_medida_base, periodo_contable, clave_pais, region_sap, poblacion_sap, grupo_vendedores, pagador, emisor_solicitante, customer_bill_to, destinatario, grupo_clientes_2, atributo_6, atributo_7, atributo_10, clase_factura, nombre_usuario, texto, numero_documento, cantidad, moneda_sociedad, fe_contabilizacion, fecha_entrada, fecha_valor, documento_comercial, hora_entrada, moneda_transaccion, clave_moneda_transaccion, moneda_fuerte, clave_moneda_fuerte, numero_doc_referencia, numero_documento_2, incoterms, incoterms_parte_2, clase_documento, cond_pago, dias_1, numero_transporte, e, tipo_embalaje, nombre_producto, volumen_toneladas, nombre_pagador, nombre_solicitante, vendedor_sap, nombre_destinatario, localidad, provincia, dpto, tipo_venta, dpto_pagador, localidad_pagador, codigo_cliente, dia, mes, anio, bonificaciones, centro_distribucion, zona_entrega, vendedor, vendedor_ok, equipo, sub_canal, region_m, ingreso_bruto, gerencia, canal)
SELECT s3.ejercicio, s3.sociedad, s3.organizacion_ventas, s3.centro, s3.division, s3.oficina_ventas, s3.canal_distribucion, s3.sector, s3.numero_cuenta, s3.centro_beneficio, s3.material, s3.unidad_medida_base, s3.periodo_contable, s3.clave_pais_region, s3.region, s3.poblacion, s3.grupo_vendedores, s3.cliente, s3.sol_ef, s3.bill_ef, s3.dest_ef, s3.grupo_clientes_2, s3.atributo_6, s3.atributo_7, s3.atributo_10, s3.clase_factura, s3.nombre_usuario, s3.texto, s3.numero_documento, s3.cantidad, CASE WHEN s3.numero_cuenta = 33111020 THEN NULL ELSE s3.moneda_sociedad END, s3.fe_contabilizacion, s3.fecha_entrada, s3.fecha_valor, s3.documento_comercial, s3.hora_entrada, s3.moneda_transaccion, s3.clave_moneda_transaccion, s3.moneda_fuerte, s3.clave_moneda_fuerte, s3.numero_doc_referencia, s3.numero_documento_2, s3.incoterms, s3.incoterms_parte_2, s3.clase_documento, s3.cond_pago, s3.dias_1, s3.numero_transporte, s3.e, s3.tipo_embalaje, s3.nombre_producto, s3.volumen_toneladas, s3.nombre_pagador, s3.nombre_solicitante, s3.vendedor_sap, s3.nombre_destinatario, s3.localidad, s3.provincia, s3.dpto, s3.tipo_venta, s3.dpto_pagador, s3.localidad_pagador, s3.codigo_cliente, s3.dia, s3.mes, s3.anio, s3.bonificaciones, s3.centro_distribucion, s3.zona_entrega, s3.vendedor, s3.vendedor_ok, s3.equipo, s3.sub_canal, s3.region_m, s3.ingreso_bruto, s3.gerencia, s3.canal FROM s3